    const nodeIds = new Set((organization && Array.isArray(organization.nodes) ? organization.nodes : []).filter(isRecord).map(node => node.id));
    const commandActions = new Set((Array.isArray(app.actions) ? app.actions : []).filter(isRecord).filter(action => action.kind === 'command').map(action => action.id));
    const text = (value, max) => typeof value === 'string' && value.trim().length > 0 && value.length <= max;
