            continue;
        const component = route.components.find((entry) => isRecord(entry) && entry.type === componentType);
        if (!isRecord(component))
            continue;
        const props = isRecord(component.props) ? component.props : {};
        const param = typeof props.param === "string" ? props.param : ROUTE_COMPONENT_PARAM_DEFAULT[componentType];
        if (!routeParamsOf(route.path).includes(param))
            continue;
